application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap');

:root { color-scheme: light; --ink: #202338; --muted: #85899f; --purple: #6655d9; --purple-dark: #5141bd; --line: #ececf4; --soft: #f7f7fc; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; font-family: 'DM Sans', sans-serif; color: var(--ink); background: linear-gradient(135deg, #f5f4ff 0%, #fbfaff 48%, #f0f8fa 100%); }
body:before { content: ''; position: fixed; width: 340px; height: 340px; border-radius: 50%; background: #dfdbff; opacity: .35; filter: blur(3px); top: -120px; right: -90px; pointer-events: none; }
.app-shell { width: min(100% - 32px, 620px); margin: 0 auto; padding: 72px 0 28px; }
.todo-card { background: rgba(255,255,255,.92); border: 1px solid rgba(255,255,255,.9); border-radius: 24px; box-shadow: 0 22px 65px rgba(73, 65, 137, .12); padding: 34px; }
.app-header { display: flex; align-items: center; gap: 15px; margin-bottom: 32px; }
.brand-mark { display: grid; place-items: center; width: 48px; height: 48px; border-radius: 15px; color: white; font-size: 25px; font-weight: 700; background: linear-gradient(145deg, #7868eb, #5746c7); box-shadow: 0 8px 18px rgba(91, 73, 202, .27); }
.eyebrow { margin: 0 0 3px; color: var(--purple); font-size: 11px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; }
h1, h2 { font-family: 'Plus Jakarta Sans', sans-serif; margin: 0; } h1 { font-size: 26px; letter-spacing: -.04em; } h2 { font-size: 16px; letter-spacing: -.02em; }
.task-form { display: flex; gap: 10px; margin-bottom: 34px; } .task-form input { flex: 1; min-width: 0; border: 1px solid #e3e3ee; border-radius: 12px; outline: none; padding: 14px 16px; color: var(--ink); font: inherit; background: #fff; transition: border .2s, box-shadow .2s; } .task-form input::placeholder { color: #b2b4c3; } .task-form input:focus { border-color: #958ae5; box-shadow: 0 0 0 4px rgba(102,85,217,.1); }
.task-form button { border: 0; border-radius: 12px; padding: 0 17px; color: white; background: var(--purple); font: 600 14px 'DM Sans', sans-serif; cursor: pointer; transition: background .2s, transform .2s; } .task-form button:hover { background: var(--purple-dark); transform: translateY(-1px); } .task-form button span { font-size: 18px; vertical-align: -1px; margin-left: 3px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 13px; } .list-heading p { margin: 0; color: var(--muted); font-size: 13px; } .list-heading p span:first-child { color: var(--purple); font-weight: 700; }
.task-list { display: flex; flex-direction: column; gap: 9px; min-height: 80px; } .task-item { display: flex; align-items: center; gap: 12px; padding: 14px 13px; border: 1px solid var(--line); border-radius: 13px; background: white; animation: slide-in .25s ease-out; } .task-item.completed { background: #fafafd; } .task-item.completed .task-text { color: #afb1be; text-decoration: line-through; }
.complete-button { flex: 0 0 auto; width: 22px; height: 22px; padding: 0; border: 1.5px solid #d2d2df; border-radius: 50%; color: transparent; background: white; cursor: pointer; transition: .2s; } .complete-button:hover { border-color: var(--purple); } .completed .complete-button { border-color: var(--purple); color: white; background: var(--purple); font-size: 14px; line-height: 19px; }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 14px; line-height: 1.4; } .delete-button { border: 0; padding: 5px; color: #b5b6c4; background: transparent; font-size: 19px; line-height: 1; cursor: pointer; } .delete-button:hover { color: #e05c70; }
.empty-state { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 144px; border: 1px dashed #dedeea; border-radius: 14px; color: var(--muted); gap: 5px; font-size: 13px; } .empty-state strong { color: #686b82; font-size: 14px; } .empty-icon { display: grid; place-items: center; width: 34px; height: 34px; margin-bottom: 4px; border-radius: 50%; color: var(--purple); background: #efedff; font-size: 18px; }
.footer-note { margin: 20px 0 0; color: #9698aa; text-align: center; font-size: 12px; }.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes slide-in { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 500px) { .app-shell { padding-top: 32px; } .todo-card { padding: 24px 18px; border-radius: 19px; } .task-form { flex-direction: column; } .task-form button { min-height: 46px; } }

application.javascript:
(function () {
  'use strict';
  const form = document.getElementById('task-form');
  const input = document.querySelector('[data-testid="task-input"]');
  const list = document.querySelector('[data-testid="task-list"]');
  const emptyState = document.getElementById('empty-state');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const countLabel = document.getElementById('count-label');
  let tasks = [];

  function render() {
    list.querySelectorAll('[data-testid="task"]').forEach(function (item) { item.remove(); });
    emptyState.hidden = tasks.length > 0;
    tasks.forEach(function (task) {
      const item = document.createElement('div');
      item.className = 'task-item' + (task.completed ? ' completed' : '');
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);
      const complete = document.createElement('button');
      complete.type = 'button'; complete.className = 'complete-button'; complete.dataset.testid = 'task-complete';
      complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      complete.setAttribute('aria-pressed', String(task.completed)); complete.textContent = task.completed ? '✓' : '';
      complete.addEventListener('click', function () { task.completed = !task.completed; render(); });
      const text = document.createElement('span'); text.className = 'task-text'; text.dataset.testid = 'task-text'; text.textContent = task.text;
      const remove = document.createElement('button'); remove.type = 'button'; remove.className = 'delete-button'; remove.dataset.testid = 'task-delete'; remove.setAttribute('aria-label', 'Delete task'); remove.textContent = '×';
      remove.addEventListener('click', function () { tasks = tasks.filter(function (entry) { return entry.id !== task.id; }); render(); });
      item.append(complete, text, remove); list.appendChild(item);
    });
    const remaining = tasks.filter(function (task) { return !task.completed; }).length;
    count.textContent = remaining; countLabel.textContent = remaining === 1 ? 'task left' : 'tasks left';
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault(); const value = input.value.trim();
    if (!value) { input.focus(); return; }
    tasks.push({ id: Date.now() + Math.random(), text: value, completed: false });
    input.value = ''; render(); input.focus();
  });
  render();
})();
